public static class BuildVaultExpansion {
 const string Root="Assets/FalloutPort/Expansion";
 static Material Mat(string name,Color color,bool unlit=false){string path=Root+"/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find(unlit?"Universal Render Pipeline/Unlit":"Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.SetColor("_BaseColor",color);return m;}
