  var game=UnityEngine.Object.FindFirstObjectByType<PortGame>();if(!game)throw new System.Exception("Open Vault120 scene first");
  var old=GameObject.Find("Vault expansion");if(old)UnityEngine.Object.DestroyImmediate(old);var root=new GameObject("Vault expansion");var steel=Mat("Military steel",new Color(.24f,.29f,.23f));var dark=Mat("Rubber",new Color(.08f,.09f,.08f));var cream=Mat("Medical enamel",new Color(.72f,.75f,.63f));var red=Mat("Medical red",new Color(.65f,.06f,.035f));var gold=Mat("Target paint",new Color(.93f,.63f,.12f));
  var interactions=game.interactions.Where(x=>x!=null&&!x.id.StartsWith("cache_")&&x.id!="range").ToList();
  Vector3[] places={new Vector3(-5.5f,0,11),new Vector3(7.7f,0,-10.2f),new Vector3(-6,0,24)};
  for(int i=0;i<3;i++){var box=new GameObject("Supply cache "+i);box.transform.SetParent(root.transform);box.transform.position=places[i];Cube("Case",box.transform,new Vector3(0,.3f,0),new Vector3(.7f,.6f,.45f),i==0?cream:steel);Cube("Lid",box.transform,new Vector3(0,.63f,0),new Vector3(.74f,.08f,.49f),dark);Cube("Latch",box.transform,new Vector3(0,.48f,-.235f),new Vector3(.1f,.16f,.025f),gold);if(i==0){Cube("Medical cross vertical",box.transform,new Vector3(0,.3f,-.234f),new Vector3(.065f,.24f,.02f),red);Cube("Medical cross horizontal",box.transform,new Vector3(0,.3f,-.235f),new Vector3(.24f,.065f,.02f),red);}var it=box.AddComponent<PortInteractable>();it.id="cache_"+i;it.displayName=i==0?"Clinic emergency supplies":i==1?"Maintenance ammunition":"Old tenant's lockbox";interactions.Add(it);}
  var console=new GameObject("Security qualification console");console.transform.SetParent(root.transform);console.transform.position=new Vector3(5.5f,0,25);Cube("Console base",console.transform,new Vector3(0,.6f,0),new Vector3(.8f,1.2f,.5f),steel);Cube("Screen",console.transform,new Vector3(0,1.28f,-.06f),new Vector3(.72f,.35f,.2f),dark);var text=new GameObject("Console instructions").AddComponent<TextMesh>();text.transform.SetParent(console.transform,false);text.transform.localPosition=new Vector3(-.32f,1.39f,-.17f);text.characterSize=.055f;text.fontSize=40;text.text="SECURITY RANGE\nE / X : QUALIFY";text.color=Color.green;var terminal=console.AddComponent<PortInteractable>();terminal.id="range";terminal.displayName="Security qualification · optional";interactions.Add(terminal);
