  game.interactions=interactions.ToArray();BuildArms(game);game.player.weapon.localPosition=new Vector3(.16f,-.12f,.55f);EditorSceneManager.MarkSceneDirty(game.gameObject.scene);EditorSceneManager.SaveScene(game.gameObject.scene);AssetDatabase.SaveAssets();return "Added three supply caches, optional security qualification and first-person arms";
 }
 static bool ArmVertex(BoneWeight w,Transform[] bones){float total=0;int[] indices={w.boneIndex0,w.boneIndex1,w.boneIndex2,w.boneIndex3};float[] weights={w.weight0,w.weight1,w.weight2,w.weight3};for(int i=0;i<4;i++){string n=bones[indices[i]].name;if(n.EndsWith(".R")&&(n.Contains("arm")||n.Contains("wrist")||n.Contains("finger")||n.Contains("metacarpal")))total+=weights[i];}return total>.7f;}
 static void BuildArms(PortGame game){var source=PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NPCCollection/Prefabs/04_Security.prefab")) as GameObject;var a=source.GetComponentInChildren<Animator>();a.runtimeAnimatorController.animationClips.First(x=>x.name.Contains("Idle_Breathe")).SampleAnimation(a.gameObject,0);var bones=source.GetComponentsInChildren<Transform>();
  foreach(string side in new[]{"R","L"}){var upper=bones.First(x=>x.name=="upperarm01."+side);var elbow=bones.First(x=>x.name=="lowerarm01."+side);var wrist=bones.First(x=>x.name=="wrist."+side);var knuckle=bones.First(x=>x.name=="finger2-1."+side);bool right=side=="R";Vector3 u=right?new Vector3(.38f,-.48f,-.38f):new Vector3(-.48f,-.48f,-.33f),e=right?new Vector3(.24f,-.3f,-.23f):new Vector3(-.28f,-.29f,-.16f),w=right?new Vector3(.045f,-.055f,-.105f):new Vector3(-.065f,-.12f,-.075f);upper.position=u;upper.rotation=Quaternion.FromToRotation(elbow.position-upper.position,e-u)*upper.rotation;elbow.position=e;elbow.rotation=Quaternion.FromToRotation(wrist.position-elbow.position,w-e)*elbow.rotation;wrist.position=w;var little=bones.First(x=>x.name=="finger5-1."+side);Vector3 palm=(knuckle.position+little.position)*.5f-wrist.position;Vector3 across=little.position-knuckle.position;var oldFrame=Quaternion.LookRotation(palm,across);var newFrame=Quaternion.LookRotation(new Vector3(-.18f,0,1),Vector3.down);wrist.rotation=newFrame*Quaternion.Inverse(oldFrame)*wrist.rotation;
   for(int digit=2;digit<=5;digit++){var first=bones.First(x=>x.name=="finger"+digit+"-1."+side);var second=bones.First(x=>x.name=="finger"+digit+"-2."+side);var third=bones.First(x=>x.name=="finger"+digit+"-3."+side);first.rotation=Quaternion.FromToRotation(second.position-first.position,new Vector3(-1,0,.12f))*first.rotation;second.rotation=Quaternion.FromToRotation(third.position-second.position,new Vector3(-.22f,0,-1))*second.rotation;third.rotation=Quaternion.AngleAxis(-35,Vector3.up)*third.rotation;}

  }
  var previous=game.player.weapon.Find("First person arms");if(previous)UnityEngine.Object.DestroyImmediate(previous.gameObject);var arms=new GameObject("First person arms");arms.layer=2;arms.transform.SetParent(game.player.weapon,false);int count=0;
  foreach(var renderer in source.GetComponentsInChildren<SkinnedMeshRenderer>()){if(renderer.name!="Head_and_hands"&&renderer.name!="Vault_TailoredJacket"&&!renderer.name.StartsWith("SewnCuff"))continue;var original=renderer.sharedMesh;var weights=original.boneWeights;var baked=UnityEngine.Object.Instantiate(original);var vs=original.vertices;var normals=original.normals;var matrices=renderer.bones.Select((b,i)=>b.localToWorldMatrix*original.bindposes[i]).ToArray();for(int i=0;i<vs.Length;i++){var w=weights[i];var v=vs[i];var n=normals[i];vs[i]=matrices[w.boneIndex0].MultiplyPoint3x4(v)*w.weight0+matrices[w.boneIndex1].MultiplyPoint3x4(v)*w.weight1+matrices[w.boneIndex2].MultiplyPoint3x4(v)*w.weight2+matrices[w.boneIndex3].MultiplyPoint3x4(v)*w.weight3;normals[i]=(matrices[w.boneIndex0].MultiplyVector(n)*w.weight0+matrices[w.boneIndex1].MultiplyVector(n)*w.weight1+matrices[w.boneIndex2].MultiplyVector(n)*w.weight2+matrices[w.boneIndex3].MultiplyVector(n)*w.weight3).normalized;}baked.vertices=vs;baked.normals=normals;for(int sub=0;sub<original.subMeshCount;sub++){var tri=original.GetTriangles(sub);var keep=new List<int>();for(int i=0;i<tri.Length;i+=3)if(ArmVertex(weights[tri[i]],renderer.bones)&&ArmVertex(weights[tri[i+1]],renderer.bones)&&ArmVertex(weights[tri[i+2]],renderer.bones)){keep.Add(tri[i]);keep.Add(tri[i+1]);keep.Add(tri[i+2]);}baked.SetTriangles(keep,sub);}baked.RecalculateBounds();string path=Root+"/FirstPersonArms_"+count+".asset";var saved=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(saved){saved.Clear();saved.vertices=baked.vertices;saved.normals=baked.normals;saved.uv=baked.uv;saved.subMeshCount=baked.subMeshCount;for(int sub=0;sub<baked.subMeshCount;sub++)saved.SetTriangles(baked.GetTriangles(sub),sub);saved.RecalculateBounds();saved.UploadMeshData(false);UnityEngine.Object.DestroyImmediate(baked);EditorUtility.SetDirty(saved);}else{AssetDatabase.CreateAsset(baked,path);saved=baked;}var part=new GameObject(renderer.name,typeof(MeshFilter),typeof(MeshRenderer));part.layer=2;part.transform.SetParent(arms.transform,false);part.GetComponent<MeshFilter>().sharedMesh=saved;var mr=part.GetComponent<MeshRenderer>();mr.sharedMaterials=renderer.sharedMaterials;mr.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;count++;}
  // A tailored sleeve extension overlaps the wrist seam without stretching skin.
  var wristR=bones.First(x=>x.name=="wrist.R");var elbowR=bones.First(x=>x.name=="lowerarm01.R");Vector3 axis=(wristR.position-elbowR.position).normalized;Vector3 xAxis=Vector3.Cross(axis,Vector3.up).normalized;Vector3 yAxis=Vector3.Cross(axis,xAxis).normalized;var cuffVertices=new Vector3[32];var cuffUV=new Vector2[32];var cuffTriangles=new List<int>();for(int ring=0;ring<2;ring++)for(int j=0;j<16;j++){float angle=j*Mathf.PI*2/16;int n=ring*16+j;cuffVertices[n]=wristR.position+axis*(ring==0?-.13f:.015f)+(xAxis*Mathf.Cos(angle)+yAxis*Mathf.Sin(angle))*(ring==0?.06f:.046f);cuffUV[n]=new Vector2(j/16f,ring);if(ring==0){int k=(j+1)%16;cuffTriangles.AddRange(new[]{j,j+16,k,k,j+16,k+16});}}var cuffMesh=new Mesh();cuffMesh.vertices=cuffVertices;cuffMesh.uv=cuffUV;cuffMesh.triangles=cuffTriangles.ToArray();cuffMesh.RecalculateNormals();cuffMesh.RecalculateBounds();string cuffPath=Root+"/GripSleeve.asset";var oldCuff=AssetDatabase.LoadAssetAtPath<Mesh>(cuffPath);if(oldCuff){oldCuff.Clear();oldCuff.vertices=cuffMesh.vertices;oldCuff.uv=cuffMesh.uv;oldCuff.triangles=cuffMesh.triangles;oldCuff.RecalculateNormals();oldCuff.RecalculateBounds();EditorUtility.SetDirty(oldCuff);UnityEngine.Object.DestroyImmediate(cuffMesh);cuffMesh=oldCuff;}else AssetDatabase.CreateAsset(cuffMesh,cuffPath);var cuffObject=new GameObject("Fitted wrist cuff",typeof(MeshFilter),typeof(MeshRenderer));cuffObject.layer=2;cuffObject.transform.SetParent(arms.transform,false);cuffObject.GetComponent<MeshFilter>().sharedMesh=cuffMesh;cuffObject.GetComponent<MeshRenderer>().sharedMaterial=source.GetComponentsInChildren<SkinnedMeshRenderer>().First(r=>r.name.StartsWith("SewnCuff")).sharedMaterial;
  UnityEngine.Object.DestroyImmediate(source);
 }
